export interface VibeConfig {
  serverURL?: string;
  service?: string;
}

/** One realtime event, as delivered to a {@link Vibe.subscribe} callback. */
export interface VibeEvent<T = unknown> {
  /** Topic leaf the event was published on — the same string you subscribed with. */
  topic: string;
  /** Server-generated id. Stable across a replay, so it is safe to dedupe on. */
  eventId: string;
  /** Publish time, epoch ms, from the publisher's clock. */
  ts: number;
  payload: T;
}

export type VibeRealtimeState = 'idle' | 'connecting' | 'open' | 'reconnecting' | 'closed';

export interface VibeSubscription {
  /** Stop receiving this topic. Safe to call more than once. */
  unsubscribe(): void;
}

/**
 * A file stored in the app's file store, as returned by {@link Vibe.uploadFile}
 * and {@link Vibe.listFiles}. `fileId` is the durable handle — hold it in state,
 * store it beside your own records, and pass it to anything that consumes a
 * file. The underlying storage path is never exposed to the browser.
 */
export interface VibeFile {
  fileId: number;
  fileName: string;
  contentType: string | null;
  size: number | null;
  uploadedTime: number | null;
  uploadedBy: number | null;
}

/**
 * Receipt for an accepted run, returned by {@link Vibe.executeFunctionAsync}.
 *
 * The function has NOT run yet, and nothing here will tell you how it went — no
 * status to poll, no event from the platform. Your handler reports its own outcome
 * on its own topic. `runId` is a correlation id: put it in the events your handler
 * publishes and the browser can tell concurrent runs apart.
 */
export interface VibeRunHandle {
  /** Correlation id for this run. Meaningful only if your handler echoes it. */
  runId: string;
  name: string;
  handler: string;
  /** Always true — the server 202'd. Says nothing about whether the run succeeds. */
  accepted: boolean;
}

export class VibeError extends Error {
  constructor(message: string, public readonly status?: number) {
    super(message);
    this.name = 'VibeError';
  }
}

export class Vibe {
  private readonly serverURL: string;
  private readonly service: string;
  /** Lazily created on the first {@link Vibe.subscribe} — an app that never
   *  subscribes never opens a socket. */
  private realtimeClient?: VibeRealtime;

  constructor(cfg: VibeConfig = {}) {
    const base = cfg.serverURL ?? (typeof window !== 'undefined' ? window.location.origin : undefined);
    if (!base) {
      throw new VibeError('VibeConfig.serverURL is required outside the browser');
    }
    this.serverURL = base.replace(/\/+$/, '');
    this.service = cfg.service ?? 'vibe';
  }

  login(redirectTo: string = currentURL()): void {
    assignLocation(this.buildAuthURL('login', redirectTo));
  }

  logout(redirectTo: string = currentURL()): void {
    assignLocation(this.buildAuthURL('logout', redirectTo));
  }

  async getCurrentUser<T = unknown>(): Promise<T | null> {
    const res = await fetch(`${this.serverURL}/api/runtime/getCurrentUser`, {
      credentials: 'include',
      headers: { Accept: 'application/json' },
    });
    if (res.status === 401) return null;
    if (!res.ok) {
      throw new VibeError(`getCurrentUser failed: ${res.status} ${res.statusText}`, res.status);
    }
    return (await res.json()) as T;
  }

  async isAuthenticated(): Promise<boolean> {
    return (await this.getCurrentUser()) !== null;
  }

  async fetch(path: string, init: RequestInit = {}): Promise<Response> {
    const url = /^https?:\/\//.test(path)
      ? path
      : `${this.serverURL}${path.startsWith('/') ? '' : '/'}${path}`;
    const res = await fetch(url, { ...init, credentials: 'include' });
    if (res.status === 401) {
      this.login();
      throw new VibeError('Not authenticated; redirecting to login', 401);
    }
    return res;
  }

  /**
   * Invoke a Connections SDK action through vibe-server.
   *
   * Routes to `POST /api/runtime/connections/{connectionSlug}/actions/{actionSlug}/execute`
   * on vibe-server, which builds a Connections SDK client for the current
   * identity and proxies the call via `ConnectionsClient.executeAction`.
   * `body` is sent as the action's JSON input (defaults to `{}`).
   */
  async executeAction<T = unknown>(
    connectionSlug: string,
    actionSlug: string,
    body: Record<string, unknown> = {},
  ): Promise<T> {
    if (!connectionSlug) throw new VibeError('connectionSlug is required');
    if (!actionSlug) throw new VibeError('actionSlug is required');
    const url =
      `${this.serverURL}/api/runtime/connections/` +
      `${encodeURIComponent(connectionSlug)}/actions/` +
      `${encodeURIComponent(actionSlug)}/execute`;
    const res = await this.fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify(body),
    });
    if (!res.ok) {
      let detail = '';
      try {
        detail = await res.text();
      } catch {
        /* ignore */
      }
      throw new VibeError(
        `executeAction ${connectionSlug}/${actionSlug} failed: ${res.status} ${res.statusText}${detail ? ` — ${detail}` : ''}`,
        res.status,
      );
    }
    if (res.status === 204) return undefined as T;
    return (await res.json()) as T;
  }

  /**
   * Upload a file to the app's file store.
   *
   * Routes to `POST /api/runtime/files` as `multipart/form-data`. The app is
   * resolved from the host the browser was served on, so uploads are scoped to
   * this app without the caller passing anything.
   *
   * Returns the stored file, whose `fileId` is the handle every consumer takes —
   * `executeAgent(..., { fileIds })`, {@link downloadFile}, {@link deleteFile},
   * or a column in your own app table. Uploads are never overwritten: two
   * uploads of `photo.png` are two files with two ids.
   *
   * `name` overrides the filename recorded server-side, which matters for a
   * `Blob` (a canvas export, a pasted screenshot) since a Blob has no name of
   * its own.
   */
  async uploadFile(file: File | Blob, name?: string): Promise<VibeFile> {
    if (!file) throw new VibeError('file is required');
    const fileName = name ?? (file instanceof File ? file.name : undefined);
    const form = new FormData();
    // Third argument only when we have a name — passing undefined explicitly
    // makes some runtimes record the literal string "undefined".
    if (fileName) form.append('file', file, fileName);
    else form.append('file', file);
    // No Content-Type header: the browser must set it, because only it knows the
    // multipart boundary it generated.
    const res = await this.fetch('/api/runtime/files', {
      method: 'POST',
      headers: { Accept: 'application/json' },
      body: form,
    });
    if (!res.ok) {
      const detail = await detailOf(res);
      throw new VibeError(
        `uploadFile ${fileName ?? ''} failed: ${res.status} ${res.statusText}${detail ? ` — ${detail}` : ''}`,
        res.status,
      );
    }
    return (await res.json()) as VibeFile;
  }

  /** This app's files, newest first. */
  async listFiles(): Promise<VibeFile[]> {
    const res = await this.fetch('/api/runtime/files', {
      headers: { Accept: 'application/json' },
    });
    if (!res.ok) {
      throw new VibeError(`listFiles failed: ${res.status} ${res.statusText}`, res.status);
    }
    const payload = (await res.json()) as { files?: VibeFile[] };
    return payload.files ?? [];
  }

  /**
   * Fetch a stored file's bytes as a `Blob`.
   *
   * For a file the user just picked, prefer `URL.createObjectURL(file)` — it
   * needs no round trip. This is for rendering or re-reading a file you only
   * have the id for.
   */
  async downloadFile(fileId: number): Promise<Blob> {
    if (!fileId) throw new VibeError('fileId is required');
    const res = await this.fetch(`/api/runtime/files/${encodeURIComponent(String(fileId))}`);
    if (!res.ok) {
      throw new VibeError(
        `downloadFile ${fileId} failed: ${res.status} ${res.statusText}`,
        res.status,
      );
    }
    return await res.blob();
  }

  /**
   * Soft-delete a stored file. Reads stop serving it immediately.
   *
   * Worth calling when a user removes an attachment before sending it —
   * otherwise the upload is left unreferenced.
   */
  async deleteFile(fileId: number): Promise<void> {
    if (!fileId) throw new VibeError('fileId is required');
    const res = await this.fetch(`/api/runtime/files/${encodeURIComponent(String(fileId))}`, {
      method: 'DELETE',
      headers: { Accept: 'application/json' },
    });
    if (!res.ok) {
      throw new VibeError(
        `deleteFile ${fileId} failed: ${res.status} ${res.statusText}`,
        res.status,
      );
    }
  }

  /**
   * Execute a Vibe agent through vibe-server.
   *
   * Routes to `POST /api/runtime/agents/{name}/run`. The server:
   *  - resolves the app from the request host (the subdomain the browser is on),
   *  - looks up the agent by (app, name) in `Vibe_Agents`,
   *  - and — if the agent was created with `stateful: true` — resolves or creates
   *    a persistent flow-ai thread scoped to the current user, so multi-turn
   *    conversations survive page reloads and device switches automatically.
   *
   * The browser sends `{ input }` plus any `fileIds` — `threadId` and
   * `outputSchema` are server-owned (thread is server-managed; outputSchema is a
   * create-time contract stored on the agent).
   *
   * Attach files by uploading them first with {@link uploadFile} and passing the
   * ids:
   *
   * ```ts
   * const photo = await vibe.uploadFile(file);
   * const res = await vibe.executeAgent('inspector', 'What is wrong here?', {
   *   fileIds: [photo.fileId],
   * });
   * ```
   *
   * The server splits them by stored content type — `image/*` goes to the
   * agent's vision input, everything else is extracted into its context — and
   * caps a single run at 10 files. Attachments belong to the run they are sent
   * with; for a stateful agent the thread already remembers them, so do not
   * re-send them on the next turn.
   *
   * Returns the flow-ai `RunResponse` verbatim: `{ runId, threadId, status,
   * response, errorMessage?, ... }`. Throws {@link VibeError} if the request
   * fails or the run errors.
   */
  async executeAgent<T = unknown>(
    name: string,
    input: string,
    opts: { fileIds?: number[] } = {},
  ): Promise<T> {
    if (!name) throw new VibeError('agent name is required');
    if (!input || !input.trim()) throw new VibeError('input is required');
    const url =
      `${this.serverURL}/api/runtime/agents/` +
      `${encodeURIComponent(name)}/run`;
    const body: Record<string, unknown> = { input };
    // Omitted entirely when empty, so the request is byte-identical to what
    // callers predating attachments send.
    if (opts.fileIds?.length) body.fileIds = opts.fileIds;
    const res = await this.fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify(body),
    });
    if (!res.ok) {
      let detail = '';
      try {
        detail = await res.text();
      } catch {
        /* ignore */
      }
      throw new VibeError(
        `executeAgent ${name} failed: ${res.status} ${res.statusText}${detail ? ` — ${detail}` : ''}`,
        res.status,
      );
    }
    const payload = (await res.json()) as { errorMessage?: string } & Record<string, unknown>;
    if (payload.errorMessage) {
      throw new VibeError(`agent ${name} errored: ${payload.errorMessage}`);
    }
    return payload as T;
  }

  /**
   * Execute a handler of a built Vibe function through vibe-server.
   *
   * Routes to `POST /api/runtime/functions/{name}/handlers/{handler}/run`, which
   * mints the backend secrets (the connections token) for the current identity
   * and invokes the function's Lambda directly. Only `args` travel from the
   * browser — secrets are never sent from the client.
   *
   * Returns the handler's output. Throws {@link VibeError} if the request fails
   * or the function itself errors.
   */
  async executeFunction<T = unknown>(
    name: string,
    handler: string,
    args: Record<string, unknown> = {},
  ): Promise<T> {
    if (!name) throw new VibeError('function name is required');
    if (!handler) throw new VibeError('handler is required');
    const url =
      `${this.serverURL}/api/runtime/functions/` +
      `${encodeURIComponent(name)}/handlers/${encodeURIComponent(handler)}/run`;
    const res = await this.fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify(args),
    });
    if (!res.ok) {
      let detail = '';
      try {
        detail = await res.text();
      } catch {
        /* ignore */
      }
      throw new VibeError(
        `executeFunction ${name}/${handler} failed: ${res.status} ${res.statusText}${detail ? ` — ${detail}` : ''}`,
        res.status,
      );
    }
    const payload = (await res.json()) as { ok?: boolean; output?: T; error?: string };
    if (payload.ok === false) {
      throw new VibeError(
        `function ${name}/${handler} errored: ${payload.error ?? 'unknown error'}`,
      );
    }
    return payload.output as T;
  }

  /**
   * Start a function run in the background and return as soon as the server accepts
   * it, without waiting for the function to finish.
   *
   * Routes to `POST /api/runtime/functions/{name}/handlers/{handler}/runAsync`. The
   * run executes as the same identity and on the same deployment channel as
   * {@link executeFunction} would, so the only difference a handler can observe is
   * that nobody is waiting for it.
   *
   * Reach for this when the work outlives the wait a user will tolerate — a bulk
   * import, a long sync, a report build. For anything the UI needs an answer to
   * right now, {@link executeFunction} is still the right call.
   *
   * **The resolved promise means accepted, not succeeded.** There is nothing to poll
   * and the platform publishes nothing — reporting is your handler's job, over the
   * realtime topics it already publishes on. Wrap the handler body in a `try/catch`
   * and publish both outcomes, or a failure is visible only in server logs.
   *
   * ```ts
   * // in the browser — subscribe first, so a fast run can't finish before you listen
   * vibe.subscribe<{ runId: string; ok: boolean; error?: string }>('imports', (evt) => {
   *   if (evt.payload.runId === myRunId && !evt.payload.ok) showError(evt.payload.error);
   * });
   * const { runId } = await vibe.executeFunctionAsync('import', 'default', { fileId });
   *
   * // in the handler — publish the runId back so the browser can correlate
   * try   { await doWork(args); await publish('imports', { runId: args.runId, ok: true }); }
   * catch (e) { await publish('imports', { runId: args.runId, ok: false, error: e.message }); }
   * ```
   *
   * Pass your own correlation value in `args` if the handler needs it — the server's
   * `runId` is not visible inside the function.
   *
   * Throws {@link VibeError} with status 429 when the app is already at its
   * concurrent-run limit — backpressure, not a bug: wait for some to finish. A 400
   * means the function is not built; that check happens up front precisely because
   * after the 202 there is no channel left to report it on.
   *
   * Two failures your handler cannot report, because they kill it from outside: the
   * `timeoutSeconds` ceiling, and a deploy mid-run. Both look like a run still in
   * progress, so give long-running UI its own timeout. Work that must not be lost
   * belongs in a scheduled job, not here.
   *
   * `timeoutSeconds` bounds one run's wall-clock (1..900, default 900).
   */
  async executeFunctionAsync(
    name: string,
    handler: string,
    args: Record<string, unknown> = {},
    opts: { timeoutSeconds?: number } = {},
  ): Promise<VibeRunHandle> {
    if (!name) throw new VibeError('function name is required');
    if (!handler) throw new VibeError('handler is required');
    const url =
      `${this.serverURL}/api/runtime/functions/` +
      `${encodeURIComponent(name)}/handlers/${encodeURIComponent(handler)}/runAsync`;
    // Always the wrapped {args} form. The bare-body form the server also accepts
    // cannot carry timeoutSeconds without risking a collision with a handler arg of
    // the same name, so the SDK never uses it here.
    const body: Record<string, unknown> = { args };
    if (opts.timeoutSeconds !== undefined) body.timeoutSeconds = opts.timeoutSeconds;
    const res = await this.fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify(body),
    });
    if (!res.ok) {
      let detail = '';
      try {
        detail = await res.text();
      } catch {
        /* ignore */
      }
      throw new VibeError(
        `executeFunctionAsync ${name}/${handler} failed: ${res.status} ${res.statusText}${detail ? ` — ${detail}` : ''}`,
        res.status,
      );
    }
    return (await res.json()) as VibeRunHandle;
  }

  /**
   * Subscribe to a realtime topic. The handler fires every time anything
   * publishes to that topic for this app — a server function, a scheduled job,
   * an agent, or another user's browser action.
   *
   * ```ts
   * const sub = vibe.subscribe<{ post: Post }>('posts', (evt) => {
   *   if (evt.payload.type === 'post.created') prependCard(evt.payload.post);
   * });
   * sub.unsubscribe();
   * ```
   *
   * All topics share ONE socket per tab, opened lazily on the first subscribe.
   * The socket authenticates with the same identity cookie as every other call
   * (it is a same-origin upgrade), and the server decides which app's events the
   * connection may see — `topic` here is only a leaf within that app, so it can
   * never reach another app's data.
   *
   * Reconnects automatically with backoff and re-subscribes on reopen. Events
   * published while disconnected are missed: `eventId` is stable, so dedupe on
   * it, and treat a reconnect as a cue to refetch if the view must be exact.
   */
  subscribe<T = unknown>(topic: string, handler: (event: VibeEvent<T>) => void): VibeSubscription {
    if (!topic) throw new VibeError('topic is required');
    if (typeof handler !== 'function') throw new VibeError('handler must be a function');
    return this.realtime().subscribe(topic, handler as (e: VibeEvent) => void);
  }

  /** Current transport state of the realtime socket. */
  get realtimeState(): VibeRealtimeState {
    return this.realtimeClient ? this.realtimeClient.state : 'idle';
  }

  /** Observe transport state — for a "live / reconnecting" indicator. Returns an
   *  unsubscribe function. */
  onRealtimeState(listener: (state: VibeRealtimeState) => void): () => void {
    return this.realtime().onState(listener);
  }

  /** Close the socket and drop every subscription. */
  closeRealtime(): void {
    this.realtimeClient?.close();
    this.realtimeClient = undefined;
  }

  private realtime(): VibeRealtime {
    if (!this.realtimeClient) {
      this.realtimeClient = new VibeRealtime(this.serverURL);
    }
    return this.realtimeClient;
  }

  private buildAuthURL(action: 'login' | 'logout', redirectTo: string): string {
    const params = new URLSearchParams({ service: this.service, redirect: redirectTo });
    return `${this.serverURL}/identity/${action}?${params.toString()}`;
  }
}

/* ------------------------------------------------------------------ *
 * Realtime transport — one WebSocket per tab, all topics multiplexed.
 *
 * Wire protocol (see vibe-server VibeWebSocketHandler):
 *   →  {"t":"sub","topics":["posts"]} | {"t":"unsub",...} | {"t":"ping"}
 *   ←  {"t":"hello",...} | {"t":"ack",...} | {"t":"event",...}
 *      | {"t":"error",...} | {"t":"pong"}
 * ------------------------------------------------------------------ */

const RECONNECT_MIN_MS = 500;
const RECONNECT_MAX_MS = 30_000;
const DEFAULT_HEARTBEAT_S = 25;
/**
 * Attempts before giving up on a socket that has never once opened. With the backoff
 * below this is roughly 30s of trying — long enough to ride out a deploy, short enough
 * not to hammer a server that is never going to accept.
 */
const MAX_INITIAL_ATTEMPTS = 6;

class VibeRealtime {
  private readonly url: string;
  private socket?: WebSocket;
  private readonly handlers = new Map<string, Set<(e: VibeEvent) => void>>();
  private readonly stateListeners = new Set<(s: VibeRealtimeState) => void>();

  private _state: VibeRealtimeState = 'idle';
  private reconnectDelay = RECONNECT_MIN_MS;
  private reconnectTimer?: ReturnType<typeof setTimeout>;
  private pingTimer?: ReturnType<typeof setInterval>;
  private watchdogTimer?: ReturnType<typeof setTimeout>;
  private heartbeatSeconds = DEFAULT_HEARTBEAT_S;
  private lastMessageAt = 0;
  /** True once a socket has reached `open` at least once. Distinguishes "the server
   *  will not accept us" from "we were connected and got dropped". */
  private everOpened = false;
  /** Consecutive attempts that never reached `open`. */
  private failedAttempts = 0;
  private onlineListener?: () => void;
  /** Set by close() so a pending reconnect doesn't resurrect the socket. */
  private closed = false;

  constructor(serverURL: string) {
    // Same origin as every other SDK call; only the scheme changes.
    this.url = `${serverURL.replace(/^http/, 'ws')}/api/runtime/events`;
  }

  get state(): VibeRealtimeState {
    return this._state;
  }

  onState(listener: (s: VibeRealtimeState) => void): () => void {
    this.stateListeners.add(listener);
    return () => this.stateListeners.delete(listener);
  }

  subscribe(topic: string, handler: (e: VibeEvent) => void): VibeSubscription {
    let set = this.handlers.get(topic);
    const isNewTopic = !set;
    if (!set) {
      set = new Set();
      this.handlers.set(topic, set);
    }
    set.add(handler);

    this.closed = false;
    if (!this.socket) {
      // An explicit subscribe is a fresh intent — clear any earlier give-up so the
      // app can retry by simply subscribing again.
      this.failedAttempts = 0;
      this.reconnectDelay = RECONNECT_MIN_MS;
      this.clearOnlineListener();
      this.connect();
    } else if (isNewTopic && this.socket.readyState === WebSocket.OPEN) {
      // Already connected — tell the server about the new topic only. On a fresh
      // connection the open handler sends the whole set instead.
      this.send({ t: 'sub', topics: [topic] });
    }

    let active = true;
    return {
      unsubscribe: () => {
        if (!active) return;
        active = false;
        const handlersForTopic = this.handlers.get(topic);
        if (!handlersForTopic) return;
        handlersForTopic.delete(handler);
        if (handlersForTopic.size > 0) return;
        // Last handler for this topic — stop the server sending it. Other topics
        // stay on the same socket, so the socket itself is left open.
        this.handlers.delete(topic);
        if (this.socket?.readyState === WebSocket.OPEN) {
          this.send({ t: 'unsub', topics: [topic] });
        }
      },
    };
  }

  close(): void {
    this.closed = true;
    this.handlers.clear();
    this.clearTimers();
    this.clearOnlineListener();
    if (this.reconnectTimer) clearTimeout(this.reconnectTimer);
    this.reconnectTimer = undefined;
    try {
      this.socket?.close();
    } catch {
      /* already closing */
    }
    this.socket = undefined;
    this.setState('closed');
  }

  private connect(): void {
    if (typeof WebSocket === 'undefined') {
      throw new VibeError('vibe.subscribe requires a browser environment (WebSocket is undefined)');
    }
    if (this.handlers.size === 0 || this.closed) return;

    this.setState(this._state === 'idle' || this._state === 'closed' ? 'connecting' : 'reconnecting');

    let socket: WebSocket;
    try {
      socket = new WebSocket(this.url);
    } catch {
      // Constructor can throw synchronously (bad URL, blocked scheme) — treat it
      // as a failed attempt so backoff still applies rather than dying here.
      this.scheduleReconnect();
      return;
    }
    this.socket = socket;

    socket.onopen = () => {
      this.reconnectDelay = RECONNECT_MIN_MS;
      this.everOpened = true;
      this.failedAttempts = 0;
      this.setState('open');
      const topics = [...this.handlers.keys()];
      if (topics.length) this.send({ t: 'sub', topics });
      this.startTimers();
    };

    socket.onmessage = (ev: MessageEvent) => {
      this.lastMessageAt = Date.now();
      let frame: Record<string, unknown>;
      try {
        frame = JSON.parse(String(ev.data));
      } catch {
        return; // not ours / truncated — ignore rather than tear down the socket
      }
      switch (frame.t) {
        case 'event': {
          const event = frame as unknown as VibeEvent;
          const set = this.handlers.get(event.topic);
          if (!set) return;
          for (const handler of [...set]) {
            try {
              handler(event);
            } catch (err) {
              // One bad handler must not stop the others, or kill the socket.
              console.error('[vibe] realtime handler threw', err);
            }
          }
          return;
        }
        case 'hello': {
          const hb = Number(frame.heartbeat);
          if (Number.isFinite(hb) && hb > 0) {
            this.heartbeatSeconds = hb;
            this.startTimers(); // re-arm with the server's interval
          }
          return;
        }
        case 'error':
          console.warn(`[vibe] realtime error: ${frame.code} — ${frame.msg}`);
          return;
        default:
          return; // ack / pong
      }
    };

    socket.onclose = () => {
      this.clearTimers();
      if (this.socket === socket) this.socket = undefined;
      this.scheduleReconnect();
    };

    socket.onerror = () => {
      // onclose always follows, and that is where reconnect is handled — doing it
      // here too would schedule two reconnects for one failure.
    };
  }

  private scheduleReconnect(): void {
    if (this.closed || this.handlers.size === 0) {
      this.setState('closed');
      return;
    }

    // A socket that has NEVER opened is a different situation from one that dropped:
    // realtime may be disabled server-side, which answers the upgrade with 503. The
    // browser does not expose a failed handshake's HTTP status to JS — a rejected
    // upgrade and an unreachable network both surface as a bare `close` — so we
    // cannot tell them apart and would otherwise retry a permanently-closed door
    // forever, once per tab. Give up after a few tries, then wait for `online` to
    // tell us something actually changed.
    if (!this.everOpened && ++this.failedAttempts >= MAX_INITIAL_ATTEMPTS) {
      console.warn(
        `[vibe] realtime could not connect after ${MAX_INITIAL_ATTEMPTS} attempts; ` +
          'giving up. Realtime may be disabled for this app. Will retry if the ' +
          'browser reports it is back online.',
      );
      this.setState('closed');
      this.waitForOnline();
      return;
    }

    this.setState('reconnecting');
    if (this.reconnectTimer) clearTimeout(this.reconnectTimer);
    // Jitter so a server restart doesn't bring every tab back in lockstep.
    const delay = this.reconnectDelay * (0.5 + Math.random());
    this.reconnectDelay = Math.min(this.reconnectDelay * 2, RECONNECT_MAX_MS);
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = undefined;
      this.connect();
    }, delay);
  }

  /**
   * Park until the browser reports connectivity, then try once more. Without this, an
   * app opened while offline would give up and stay dead even after the network came
   * back.
   */
  private waitForOnline(): void {
    if (this.onlineListener || typeof window === 'undefined') return;
    this.onlineListener = () => {
      this.clearOnlineListener();
      if (this.closed || this.handlers.size === 0) return;
      this.failedAttempts = 0;
      this.reconnectDelay = RECONNECT_MIN_MS;
      this.connect();
    };
    window.addEventListener('online', this.onlineListener);
  }

  private clearOnlineListener(): void {
    if (this.onlineListener && typeof window !== 'undefined') {
      window.removeEventListener('online', this.onlineListener);
    }
    this.onlineListener = undefined;
  }

  private startTimers(): void {
    this.clearTimers();
    const intervalMs = this.heartbeatSeconds * 1000;
    this.lastMessageAt = Date.now();
    this.pingTimer = setInterval(() => this.send({ t: 'ping' }), intervalMs);
    // A TCP connection can be dead without either side noticing (laptop sleep,
    // NAT timeout, silently dropped LB connection). If nothing arrives for well
    // over one heartbeat, assume it is gone and force a reconnect.
    this.watchdogTimer = setInterval(() => {
      if (Date.now() - this.lastMessageAt > intervalMs * 2.5) {
        try {
          this.socket?.close();
        } catch {
          /* ignore */
        }
      }
    }, intervalMs) as unknown as ReturnType<typeof setTimeout>;
  }

  private clearTimers(): void {
    if (this.pingTimer) clearInterval(this.pingTimer);
    if (this.watchdogTimer) clearInterval(this.watchdogTimer as unknown as ReturnType<typeof setInterval>);
    this.pingTimer = undefined;
    this.watchdogTimer = undefined;
  }

  private send(frame: Record<string, unknown>): void {
    if (this.socket?.readyState !== WebSocket.OPEN) return;
    try {
      this.socket.send(JSON.stringify(frame));
    } catch {
      /* socket died mid-send; onclose will drive the reconnect */
    }
  }

  private setState(next: VibeRealtimeState): void {
    if (this._state === next) return;
    this._state = next;
    for (const listener of [...this.stateListeners]) {
      try {
        listener(next);
      } catch {
        /* ignore listener errors */
      }
    }
  }
}

function currentURL(): string {
  if (typeof window === 'undefined') {
    throw new VibeError('Vibe SDK requires a browser environment (window is undefined)');
  }
  return window.location.href;
}

function assignLocation(url: string): void {
  if (typeof window === 'undefined') {
    throw new VibeError('Vibe SDK requires a browser environment (window is undefined)');
  }
  window.location.assign(url);
}

/** Server error body, best effort — a failure to read it must not mask the status. */
async function detailOf(res: Response): Promise<string> {
  try {
    return await res.text();
  } catch {
    return '';
  }
}

export function createVibe(cfg: VibeConfig = {}): Vibe {
  return new Vibe(cfg);
}

/* ------------------------------------------------------------------ *
 * Connected-app SDK — iframe <-> host bridge.
 *
 * Wire protocol is identical to the legacy `facilio-apps-sdk`, so the
 * existing Facilio host handles these messages unchanged. Trimmed to
 * the surface Vibe needs: currentOrg/app/user/context + isMobile() +
 * `interface` namespace (which includes `interface.trigger`).
 * ------------------------------------------------------------------ */

const VIBE_SDK_VERSION = '0.1.4';
const FCA_EVENT = /^fca\./;

export interface ConnectedAppConfig {
  /** Parent origin. Defaults to `?origin=` / `#origin=` from the current URL. */
  origin?: string;
  /** Connected-app instance id. Defaults to `?capp_id=` / `#capp_id=`. */
  cappId?: string;
}

export interface ConnectedAppLoadedData {
  currentUser?: unknown;
  currentOrg?: unknown;
  currentApp?: unknown;
  context?: unknown;
  widget?: unknown;
  exportMode?: boolean;
}

type MessageTarget = { postMessage: (msg: string, targetOrigin?: string) => void };

export class ConnectedAppInterface {
  constructor(private readonly client: ConnectedApp) {}

  navigateTo(options: { path?: string; query?: unknown }): Promise<unknown> {
    return this.client._postMessageWithPromise('interface.navigateTo', {
      path: options.path,
      query: options.query,
    });
  }

  openSummary(options: { module: string; id: number | string }, newtab = false): Promise<unknown> {
    return this.client._postMessageWithPromise('interface.openSummary', {
      module: options.module,
      id: options.id,
      newtab,
    });
  }

  openListView(
    options: { module: string; view?: string; filters?: unknown },
    newtab = false,
  ): Promise<unknown> {
    return this.client._postMessageWithPromise('interface.openListView', {
      module: options.module,
      view: options.view,
      filters: options.filters,
      newtab,
    });
  }

  openForm(
    options: { module: string; formDetails?: unknown },
    newtab = false,
  ): Promise<unknown> {
    return this.client._postMessageWithPromise('interface.openForm', {
      module: options.module,
      formDetails: options.formDetails,
      newtab,
    });
  }

  openQRScanner(options: Record<string, unknown> = {}): Promise<unknown> {
    return this.client._postMessageWithPromise('interface.openQRScanner', options);
  }

  openAnalytics(
    options: { dataPoints?: unknown; dateRange?: unknown; xAggr?: unknown },
    newtab = false,
  ): Promise<unknown> {
    return this.client._postMessageWithPromise('interface.openAnalytics', {
      dataPoints: options.dataPoints,
      dateRange: options.dateRange,
      xAggr: options.xAggr,
      newtab,
    });
  }

  showTrend(options: { dataPoints?: unknown; dateRange?: unknown; xAggr?: unknown }): Promise<unknown> {
    return this.client._postMessageWithPromise('interface.showTrend', {
      dataPoints: options.dataPoints,
      dateRange: options.dateRange,
      xAggr: options.xAggr,
    });
  }

  showControl(options: {
    resourceId: number | string;
    readingId: number | string;
    groupId?: number | string;
  }): Promise<unknown> {
    return this.client._postMessageWithPromise('interface.showControl', {
      resourceId: options.resourceId,
      readingId: options.readingId,
      groupId: options.groupId,
    });
  }

  fullscreen(): Promise<unknown> {
    return this.client._postMessageWithPromise('interface.fullscreen', {});
  }

  triggerDownload(fileId: number | string, fileName?: string): Promise<unknown> {
    return this.client._postMessageWithPromise('interface.triggerDownload', {
      fileId,
      fileName,
    });
  }

  notify(options: unknown): Promise<unknown> {
    return this.client._postMessageWithPromise('interface.notify', { options });
  }

  openURL(options: Record<string, unknown> = {}): Promise<unknown> {
    return this.client._postMessageWithPromise('interface.openURL', options);
  }

  getCurrentPage(): Promise<unknown> {
    return this.client._postMessageWithPromise('interface.getCurrentPage', {});
  }

  trigger(namespace: string, options?: unknown): Promise<unknown> {
    return this.client._postMessageWithPromise('interface.trigger', { namespace, options });
  }
}

export class ConnectedApp {
  currentOrg: unknown = null;
  app: unknown = null;
  user: unknown = null;
  context: unknown = null;

  readonly interface: ConnectedAppInterface;
  /** Resolves once the host has sent `app.loaded` and the fields above are populated. */
  readonly ready: Promise<void>;

  private readonly _origin: string;
  private readonly _cappId: string;
  private readonly _source: MessageTarget;
  private readonly _isMobile: boolean;
  private readonly _pending = new Map<
    number,
    { resolve: (v: unknown) => void; reject: (e: Error) => void }
  >();
  private _promiseId = 0;
  private _resolveReady!: () => void;

  constructor(cfg: { origin: string; cappId: string }) {
    if (typeof window === 'undefined') {
      throw new VibeError('ConnectedApp requires a browser environment (window is undefined)');
    }
    this._origin = cfg.origin;
    this._cappId = cfg.cappId;

    const rn = (window as unknown as { ReactNativeWebView?: MessageTarget }).ReactNativeWebView;
    this._isMobile = rn != null;
    this._source = rn ?? (window.parent as unknown as MessageTarget);

    this.ready = new Promise<void>((resolve) => {
      this._resolveReady = resolve;
    });
    this.interface = new ConnectedAppInterface(this);

    window.addEventListener('message', this._onMessage);
    this._postMessage('app.handshake', { version: VIBE_SDK_VERSION });
  }

  isMobile(): boolean {
    return this._isMobile;
  }

  /** @internal — used by ConnectedAppInterface. */
  _postMessageWithPromise(key: string, params: unknown): Promise<unknown> {
    const id = ++this._promiseId;
    return new Promise<unknown>((resolve, reject) => {
      this._pending.set(id, { resolve, reject });
      this._send({ id, key, params, instanceUid: this._cappId });
    });
  }

  private _postMessage(key: string, params: unknown): void {
    this._send({ key, params, instanceUid: this._cappId });
  }

  private _send(payload: unknown): void {
    const msg = JSON.stringify(payload);
    if (this._isMobile) {
      this._source.postMessage(msg);
    } else {
      this._source.postMessage(msg, this._origin);
    }
  }

  private _isValidEvent(event: MessageEvent): boolean {
    if (this._isMobile) return true;
    return event.origin === this._origin && event.source === (this._source as unknown as MessageEventSource);
  }

  private _onMessage = (event: MessageEvent): void => {
    if (!this._isValidEvent(event)) return;
    let data: unknown = event.data;
    if (typeof data === 'string') {
      try {
        data = JSON.parse(data);
      } catch {
        return;
      }
    }
    if (!data || typeof data !== 'object') return;
    const d = data as {
      id?: number;
      key?: string;
      result?: unknown;
      error?: unknown;
      message?: unknown;
    };

    if (typeof d.id === 'number' && this._pending.has(d.id)) {
      const p = this._pending.get(d.id)!;
      this._pending.delete(d.id);
      if (d.error) {
        const e = d.error as { message?: string } | string;
        const msg =
          typeof e === 'object' && e && 'message' in e && typeof e.message === 'string'
            ? e.message
            : String(e);
        p.reject(new Error(msg));
      } else {
        p.resolve(d.result);
      }
      return;
    }

    if (typeof d.key === 'string' && FCA_EVENT.test(d.key)) {
      const eventName = d.key.replace(FCA_EVENT, '');
      if (eventName === 'app.loaded') {
        const loaded = (d.message ?? {}) as ConnectedAppLoadedData;
        this.currentOrg = loaded.currentOrg ?? null;
        this.app = loaded.currentApp ?? null;
        this.user = loaded.currentUser ?? null;
        this.context = loaded.context ?? null;
        this._resolveReady();
      }
    }
  };
}

function parseQueryParams(qs: string): Record<string, string> {
  const out: Record<string, string> = {};
  if (!qs) return out;
  if (qs[0] === '?' || qs[0] === '#') qs = qs.slice(1);
  if (!qs.length) return out;
  for (const pair of qs.split('&')) {
    const [rawKey, rawVal = ''] = pair.split('=');
    if (!rawKey) continue;
    const key = decodeURIComponent(rawKey.replace(/\+/g, ' '));
    const val = decodeURIComponent(rawVal.replace(/\+/g, ' '));
    out[key] = val;
  }
  return out;
}

/**
 * Boot the iframe-side connected-app SDK, wait for the host to complete
 * the `app.handshake` / `app.loaded` round-trip, and resolve with a
 * hydrated {@link ConnectedApp}.
 *
 * `origin` and `capp_id` default to values parsed from the current URL's
 * query string or hash — supplied by the Facilio host when it renders
 * the app iframe.
 */
export async function initConnectedApp(cfg: ConnectedAppConfig = {}): Promise<ConnectedApp> {
  if (typeof window === 'undefined') {
    throw new VibeError('initConnectedApp requires a browser environment (window is undefined)');
  }
  const q = parseQueryParams(window.location.search);
  const h = parseQueryParams(window.location.hash);
  const origin = cfg.origin ?? q.origin ?? h.origin;
  const cappId = cfg.cappId ?? q.capp_id ?? h.capp_id;
  if (!origin) {
    throw new VibeError(
      'initConnectedApp: `origin` not found — pass it in cfg or ensure the host appended ?origin=...',
    );
  }
  if (!cappId) {
    throw new VibeError(
      'initConnectedApp: `capp_id` not found — pass it in cfg.cappId or ensure the host appended ?capp_id=...',
    );
  }
  const app = new ConnectedApp({ origin, cappId });
  await app.ready;
  return app;
}
